post=r"""
const SEXL={F:'Female',M:'Male',X:'Another term'};
const HXSEED={1:[['Type 2 diabetes','2019','Active']],3:[['Childhood immunisation schedule','2019','Active']],4:[['Hypertension','2014','Active'],['Type 2 diabetes','2016','Active']],6:[['Hypertension','2009','Active']],9:[['Type 2 diabetes','2021','Active']],8:[['Cervical screening recall','2023','Active']]};
S.pts.forEach(p=>{if(!p.hx)p.hx=HXSEED[p.id]||[];if(!p.cons)p.cons=[['Privacy collection notice','Given at registration','on'],['Treatment consent','Given at registration','on'],['My Health Record participation','Not recorded (simulated)','off'],['Marketing SMS','Opted out','off']];if(p.id===4&&p.hdr===undefined)p.hdr='Prefers phone calls in the morning'});
S.news=S.news||[['Flu vaccine stock arrives Thursday','Nurse team'],['Server maintenance Sunday 2am (simulated)','Practice manager']];
const ic2={sms:'M4 5h16v11H8l-4 4zM8 9h8M8 12h5',msg:'M4 6h16v12H4zM4 7l8 6 8-6',inv:'M5 4h14v16l-3-2-2 2-2-2-2 2-2-2-3 2zM9 9h6M9 13h6',cal:'M4 5h16v15H4zM4 10h16M9 3v4M15 3v4',act:'M9 11l2 2 4-4M5 4h14v16H5z',con:'M8 3h8l3 3v15H5V3zM9 11h6M9 15h6',mail:'M4 6h16v12H4zM4 7l8 6 8-6',user:'M12 12a4 4 0 100-8 4 4 0 000 8zM4 21c0-4 4-6 8-6s8 2 8 6'};
const ii=(k,s=16)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" aria-hidden="true"><path d="${ic2[k]}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const mdBar=()=>{const I=integ(),att=I.filter(x=>['fail','unc','review'].includes(x[2])),o=!!UI.ibOpen;return `<div class="ibar${o?' open':''}" role="region" aria-label="Integration status, simulated"><button class="btn sm" type="button" data-act="ibT" aria-expanded="${o}">Integrations, simulated: ${att.length} need attention</button>${(o?I:att).map(([k,n2,s,d])=>`<a href="#/comp/integ" title="${esc(d)}"><span>${n2}</span>${stChip(s)}</a>`).join('')}</div>`};
ACT.ibT=()=>{UI.ibOpen=!UI.ibOpen;R()};
// ---- top: quicklinks bar ----
const unreadN=()=>S.results.filter(r=>r.st!=='reviewed').length+S.msgs.filter(m=>m.st==='unread').length;
function mdTop(r){const n=unreadN();return `<header class="top mdq"><div class="qlk" role="group" aria-label="Quick links"><button class="qb pat" type="button" data-act="newPt">+ Patient</button><button class="qb apt" type="button" data-act="newAppt">+ Appointment</button><button class="qb ca" type="button" data-act="mdCA">+ Clinical action</button><button class="qb tsk" type="button" data-act="taskNew">+ Task</button></div><div class="find"><button class="cmd" type="button" data-act="palette"><svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><circle cx="7" cy="7" r="4.5" fill="none" stroke="currentColor" stroke-width="2"/><path d="M10.5 10.5L14 14" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg><span>Find a patient</span></button></div><label class="loc"><span class="sr">Location</span><select><option>Harbour Street</option><option>Northside</option><option>Telehealth hub</option></select></label><a class="ibtn" href="#/res" aria-label="Inbox, ${n} to review">${ii('mail',18)}${n?`<span class="nb">${n}</span>`:''}</a><a class="ibtn" href="#/book" aria-label="Appointments">${ii('cal',18)}</a><details class="um"><summary aria-label="User menu">${ini(DOCS.nair.n)}</summary><ul><li><button type="button" data-act="toastC" data-m="Profile (demo).">Profile</button></li><li><button type="button" data-act="toastC" data-m="Preferences (demo): consult and calendar options.">Preferences</button></li><li><button type="button" data-act="toastC" data-m="Help and support (demo).">Help and support</button></li><li><button type="button" data-act="toastC" data-m="Log out is not part of this mockup.">Log out</button></li></ul></details></header>`}
ACT.mdCA=el=>{if(!need('comms','Creating a clinical action'))return;const pre=el&&el.dataset&&el.dataset.id?+el.dataset.id:'';formModal({title:'New clinical action',submit:'Save action',fields:[{k:'p',l:'Patient',t:'select',req:true,v:pre,o:[['','Choose patient'],...S.pts.map(p=>[p.id,nm(p)])]},{k:'a',l:'Action',t:'select',o:['Phone patient','Review results','Book recall','Send letter','Other'].map(x=>[x,x])},{k:'due',l:'Due',v:'Today'},{k:'who',l:'Assign to',t:'select',o:Object.keys(ROLE).map(k=>[k,ROLE[k]]),v:'gp'},{k:'n',l:'Notes',t:'textarea'}],save:v=>{S.tasks.unshift({id:++S.next,t:v.a+': '+nm(P(v.p))+(v.n?'. '+v.n:''),who:v.who,due:v.due||'Today',done:false,p:+v.p,ca:1});audit('Created clinical action',nm(P(v.p)));persist();R();toast('Clinical action saved.')}})};
// ---- home ----
function mdHome(){const due=S.pts.filter(p=>p.flags.some(f=>/due/i.test(f)));const ur=S.results.filter(r=>r.st==='review').length,hold=S.results.filter(r=>r.st==='unmatched').length,cu=S.msgs.filter(m=>m.st==='unread').length;
 return `<div class="vh"><h1>Home</h1><a class="btn pri" href="#/book">Open appointments</a></div><div class="dsh"><div class="col">${pnl('mh-a',"Today's appointments",apptList(),DOCS[UI.doc]?DOCS[UI.doc].n:'All providers')}${pnl('mh-p','Preventative health due',due.map(p=>`<div class="q"><span><a href="#/pts/${p.id}/dashboard" data-act="openPt" data-id="${p.id}"><b>${esc(nm(p))}</b></a><br><span class="muted">${p.flags.filter(f=>/due/i.test(f)).join(', ')}</span></span><span><button class="btn sm" type="button" data-act="mdCA" data-id="${p.id}">Create action</button></span></div>`).join('')||'<p class="muted">Nothing due.</p>',due.length+' patients')}</div>
 <div class="col">${pnl('mh-i','Inbox',`<div class="q"><span>Results to review</span><a class="btn sm" href="#/res/results">${ur}</a></div><div class="q"><span>Correspondence unread</span><a class="btn sm" href="#/res/correspondence">${cu}</a></div><div class="q"><span>Holding bay, not matched</span><a class="btn sm" href="#/res/holding">${hold}</a></div>`,'secure messaging, simulated')}${pnl('mh-t','My activities',`<ul class="tasks">${taskRows(true)}</ul><div class="row-actions"><a class="btn sm" href="#/inbox">All activities</a></div>`,S.tasks.filter(t=>!t.done&&t.who===S.role).length+' open')}${aiPanelHome()}${pnl('mh-n','Notice board',`<ul class="mlist">${S.news.map(n=>`<li><span>${esc(n[0])}</span><span class="muted">${esc(n[1])}</span></li>`).join('')}</ul>`,'')}</div></div>`}
// ---- appointments page ----
const LGD=[['late','Late'],['un','Unavailable'],['booked','Booked'],['confirmed','Confirmed'],['arrived','Waiting room'],['with','With provider'],['billing','At billing'],['done','Completed'],['dna','Did not attend']];
ON.cq=el=>{UI.cq=el.value;R()};ON.mdProv=el=>{const k=el.dataset.k,m=cd();m[k]=el.checked;if(!Object.keys(DOCS).some(x=>m[x]))m[k]=true;R()};ON.mdSt=el=>{UI.cst=UI.cst||{};UI.cst[el.dataset.k]=el.checked;R()};
function mdCalPage(){const d=UI.d,v=UI.cv,rng=v==='month'?monthLabel():v==='week'?dayFull(d)+' to '+dayFull(d+4):dayFull(d),m=cd();
 const body=v==='day'?calDay():v==='week'?calWeek():v==='month'?calMonth():v==='times'?freeSlotsPanel():`<div class="panel"><div class="pb" style="padding-top:12px">${apptList()}</div></div>`;
 const tabs=[['day','Day'],['week','Week'],['month','Month'],['list','Agenda'],['times','Available times']];
 return `<h1 class="sr">Appointments</h1><div class="mdh"><div class="l"><button class="btn sm" type="button" data-act="calToday">Today</button><span class="btn-group"><button class="btn sm" type="button" data-act="calNav" data-n="-1" aria-label="Previous" ${(v==='month'?UI.m===0:d===0)?'disabled':''}>&lsaquo;</button><button class="btn sm" type="button" data-act="calNav" data-n="1" aria-label="Next" ${(v==='month'?UI.m>=3:d>=53)?'disabled':''}>&rsaquo;</button></span><span class="rng" aria-live="polite">${rng}</span></div>
 <div class="r"><label class="sr" for="cq">Search patient</label><input id="cq" type="search" placeholder="Search patient" value="${esc(UI.cq||'')}" data-on="input" data-fn="cq"><span class="vtabs" role="group" aria-label="View">${tabs.map(([k,l])=>`<button type="button" aria-pressed="${v===k}" data-act="calView" data-id="${k}">${l}</button>`).join('')}</span><span class="sms">SMS balance 1,240 (simulated)</span>
 <details class="dd"><summary>Providers &#9662;</summary><div class="ddm">${Object.keys(DOCS).map(k=>`<label><input type="checkbox" ${m[k]?'checked':''} data-on="mdProv" data-k="${k}"> ${DOCS[k].n}</label>`).join('')}</div></details>
 <details class="dd"><summary>Filter &#9662;</summary><div class="ddm">${LGD.filter(x=>x[0]!=='un').map(([k,l])=>`<label><input type="checkbox" ${(UI.cst||{})[k]!==false?'checked':''} data-on="mdSt" data-k="${k}"> ${l}</label>`).join('')}</div></details>
 <span class="btn-group zoom"><button class="btn sm" type="button" data-act="calZoom" data-n="-1" aria-label="Zoom out" ${UI.zoom<=ZS[0]?'disabled':''}>&minus;</button><button class="btn sm" type="button" data-act="calZoom" data-n="1" aria-label="Zoom in" ${UI.zoom>=ZS[3]?'disabled':''}>+</button></span><button class="btn pri" type="button" data-act="newAppt">New appointment</button></div></div>
 <div class="calwrap"><div class="calmain">${body}</div></div><div class="mdlg" role="group" aria-label="Status legend">${LGD.map(([k,l])=>`<span><span class="sw s-${k}"></span>${l}</span>`).join('')}</div>`}
// ---- patients ----
const TABS=[['dashboard','Dashboard'],['details','Details'],['clinical','Clinical'],['accounts','Accounts'],['consent','Consent'],['activities','Activities'],['audit','Audit']];
const ALIAS={summary:['dashboard'],notes:['clinical','past'],results:['clinical','investigations'],billing:['accounts'],care:['activities']};
const PV=[['all','All patients',()=>true],['owing','Owing',p=>bal(p.id)>0],['allergy','Allergy alert',p=>p.al.length>0],['recall','Recall or review due',p=>p.flags.some(f=>/due/i.test(f))]];
ON.mdq=el=>{UI.pq=el.value;R()};
function mdPtList(){const q=UI.pq.toLowerCase().replace(/\s/g,''),pv=PV.find(x=>x[0]===(UI.pv||'all'));const L2=S.pts.filter(p=>pv[2](p)&&(!q||(nm(p)+p.ph+p.mc).toLowerCase().replace(/\s/g,'').includes(q))).sort((a,b)=>a.ln.localeCompare(b.ln));
 const nx=id=>{const a=S.appts.filter(x=>x.p===id&&['booked','online','arrived'].includes(x.st)).sort((x,y)=>x.d-y.d||x.t-y.t)[0];return a?dayName(a.d)+' '+hm(a.t):'None'};
 return `<div class="vh"><h1>Patients</h1><button class="btn pri" type="button" data-act="newPt">+ Patient</button></div><div class="panel"><div class="pb" style="padding-top:12px"><div class="itabs" role="group" aria-label="Patient views">${PV.map(([k,l,f])=>`<button type="button" aria-pressed="${(UI.pv||'all')===k}" data-act="mdPV" data-id="${k}">${l} ${S.pts.filter(f).length}</button>`).join('')}</div>
 <div class="fld"><label for="mdq">Search by name, mobile number or Medicare number</label><input id="mdq" type="search" value="${esc(UI.pq)}" data-on="input" data-fn="mdq" autocomplete="off"></div>
 <div class="scroll-x"><table class="tbl ptbl"><thead><tr><th>Name</th><th>Born</th><th>Sex</th><th>Mobile</th><th>Medicare</th><th>Next appointment</th><th>Alerts</th></tr></thead><tbody>${L2.map(p=>`<tr class="rowlk" data-act="openPt" data-id="${p.id}"><td><a href="#/pts/${p.id}/dashboard" data-act="openPt" data-id="${p.id}"><b>${esc(p.ln)}, ${esc(p.fn)}</b></a></td><td class="num">${dobS(p.dob)} (${age(p.dob)})</td><td>${SEXL[p.sex]||p.sex}</td><td class="num">${esc(p.ph)}</td><td class="num">${mcm(p)}</td><td>${nx(p.id)}</td><td>${flags(p)||'<span class="muted">None</span>'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No patient found.</td></tr>'}</tbody></table></div>
 <div class="row-actions"><button class="btn sm" type="button" data-act="mdBulk" data-n="${L2.length}">Send bulk SMS to ${L2.length} (simulated)</button><button class="btn sm" type="button" data-act="toastC" data-m="Export simulated. A real build writes a CSV.">Export list (simulated)</button></div></div></div>`}
ACT.mdPV=el=>{UI.pv=el.dataset.id;R()};ACT.mdBulk=el=>{if(!need('comms','Sending bulk SMS'))return;confirmDlg('Send bulk SMS (simulated)','This would queue a message to '+el.dataset.n+' patients. Nothing is really sent.','Queue (simulated)',()=>{audit('Bulk SMS queued (simulated)',el.dataset.n+' patients');toast('Queued as a simulation. Nothing was sent.')})};
function mdHdr(p){const act=S.tasks.filter(t=>t.p===p.id&&!t.done).length;return `<section class="mdph" aria-label="Patient"><div class="av2" aria-hidden="true">${esc(p.fn[0]+p.ln[0])}</div><div class="hn"><h1>${esc(nm(p))}</h1><span class="muted">${SEXL[p.sex]||p.sex}, ${age(p.dob)} years, born ${dobS(p.dob)}, mobile ${esc(p.ph)}, Medicare ${mcm(p)} (masked)</span><div class="al">${flags(p)}</div>${p.hdr?`<p class="hdrnote"><b>Note:</b> ${esc(p.hdr)}</p>`:''}</div><div class="hr">${chip(act?'warn':'neu',act?act+' open activities':'No activities recorded')}<button class="btn sm" type="button" data-act="toastC" data-m="Practice chat opened (simulated).">Chat</button><button class="btn sm" type="button" data-act="toastC" data-m="Portal invitation would be sent (simulated).">Engage</button></div></section>`}
function mdQA(p){const t=S.appts.find(x=>x.p===p.id&&x.d===0&&['with','arrived','booked','online'].includes(x.st));return `<div class="qa" role="toolbar" aria-label="Quick actions"><button class="btn sm" type="button" data-act="mdSms" data-id="${p.id}">${ii('sms')} SMS on demand</button><button class="btn sm" type="button" data-act="mdMsgs" data-id="${p.id}">${ii('msg')} Messages</button><button class="btn sm" type="button" data-act="mdInv" data-id="${p.id}">${ii('inv')} Invoice</button><button class="btn sm" type="button" data-act="newAppt" data-p="${p.id}">${ii('cal')} Appointment</button><button class="btn sm" type="button" data-act="mdCA" data-id="${p.id}">${ii('act')} Clinical action</button><button class="btn sm" type="button" ${t?`data-act="start" data-id="${t.id}"`:'data-act="toastC" data-m="No appointment today. Book or arrive the patient first."'}>${ii('con')} Consultation</button></div>`}
ACT.mdSms=el=>{if(!need('comms','Sending SMS'))return;const p=P(el.dataset.id);formModal({title:'SMS on demand (simulated)',submit:'Send (simulated)',fields:[{k:'t',l:'Template',t:'select',o:[['','None, free text'],['rem',S.tmpl.rem.replace('{first}',p.fn).replace('{doctor}','Dr Nair').replace('{date}','Thu').replace('{time}','09:20')],['rec',S.tmpl.recall.replace('{first}',p.fn).replace('{reason}','a check-up')]]},{k:'m',l:'Message',t:'textarea',req:true}],save:v=>{audit('SMS on demand (simulated)',nm(p));persist();toast('Marked sent. Simulated, nothing left this page.')}});const sel=$('#f-t');sel&&(sel.onchange=()=>{$('#f-m').value=sel.value?sel.options[sel.selectedIndex].text:''})};
ACT.mdMsgs=el=>{const p=P(el.dataset.id),L2=S.msgs.filter(m=>m.p===p.id);openModal({title:'Messages, '+nm(p),body:L2.map(m=>`<div class="q"><span><b>${esc(m.sub)}</b><br><span class="muted">${esc(m.from)}</span></span>${m.st==='fail'?stChip('fail'):m.dir==='out'?stChip('sent'):chip('neu','Received')}</div>`).join('')||'<p class="muted">No messages for this patient.</p>',foot:'<button class="btn" data-act="close">Close</button>'})};
ACT.mdInv=el=>{if(!need('billing','Creating an invoice'))return;const p=P(el.dataset.id);formModal({title:'New invoice, '+nm(p),submit:'Create draft',fields:[{k:'k',l:'Invoice type',t:'select',o:[['out','New invoice'],['in','New in-patient invoice (simulated)']]},{k:'ty',l:'Item',t:'select',o:Object.entries(TYPES).map(([k,t])=>[k,t[0]+' ('+money(FEES[k])+')'])}],save:v=>{S.inv.push({id:++S.next,p:p.id,a:null,items:[[TYPES[v.ty][0]+' (demo item)',FEES[v.ty]]],paid:0,st:'draft',claim:null});audit('Created invoice draft',nm(p));persist();go('pts/'+p.id+'/accounts');toast('Draft invoice created.')}})};
// dashboard
function mdDash(p){const cv=can('clin.view'),f=S.results.filter(r=>r.p===p.id);const w=(t,b,btn)=>`<section class="wgt" aria-label="${t}"><h2>${t}</h2><ul>${b}</ul>${btn||''}</section>`;
 const lnk=(s,l)=>`<a class="btn sm" href="#/pts/${p.id}/clinical/${s}">${l}</a>`;
 const tab=UI.dsub||'summary';
 const widgets=cv?w('Current medications',p.meds.filter(m=>m[2]!=='off').slice(0,3).map(m=>`<li><b>${m[0]}</b> ${m[1]}</li>`).join('')||'<li class="muted">None recorded</li>',lnk('medications','View current Rx'))
  +w('Medical history',p.hx.slice(0,3).map(h=>`<li class="${/asthma|uncontrolled/i.test(h[0])?'red':''}">${esc(h[0])}, since ${h[1]}</li>`).join('')||'<li class="muted">None recorded</li>',lnk('history','View medical history'))
  +w('Allergies and reactions',p.al.map(a=>`<li class="red">${esc(a)} (keyword demo)</li>`).join('')||'<li class="muted">No known allergies recorded</li>',lnk('allergies','View allergies'))
  +w('Immunisations',p.imm.slice(0,3).map(i=>`<li><b>${i.v}</b> ${i.d}<br>${stChip(i.air)}</li>`).join('')||'<li class="muted">None recorded</li>',lnk('immunisations','View immunisations'))
  +w('Investigations',f.slice(0,3).map(r=>`<li><b>${esc(r.test)}</b> ${r.at}<br>${r.st==='reviewed'?chip('ok','Reviewed'):chip('warn','Needs review')}</li>`).join('')||'<li class="muted">None recorded</li>',lnk('investigations','View investigations'))
  +(p.sex==='F'&&age(p.dob)>=14&&age(p.dob)<=55?w('Pregnancy details','<li class="muted">No pregnancy details recorded</li>',lnk('obstetrics','View current pregnancy')):w('Observations',p.obs.slice(0,3).map(o=>`<li>${o[0]} <b>${o[1]} ${o[2]}</b> <span class="muted">${o[3]}</span></li>`).join('')||'<li class="muted">None recorded</li>',lnk('observations','View observations'))):`<div class="notice">Clinical widgets are hidden for the ${ROLE[S.role]} role (need-to-know). Switch role in the demo bar.</div>`;
 const notes=S.notes.filter(n=>n.p===p.id).slice(-10).reverse();
 const pt=UI.pdt||'ph';
 const al=p.flags.map(f=>/due/i.test(f)?f.toUpperCase().replace(' DUE',' IS DUE'):f).map((f,i)=>`<div class="pha ${/due/i.test(f)?'':'w'}"><span>${esc(f)}</span><button class="btn" type="button" data-act="mdCA" data-id="${p.id}" aria-label="Create action for ${esc(f)}">+</button></div>`).join('')||'<p class="muted">No preventative health alerts.</p>';
 const chat=S.msgs.filter(m=>m.p===p.id).map(m=>`<div class="q"><span><b>${esc(m.sub)}</b><br><span class="muted">${esc(m.from)}</span></span></div>`).join('')||'<p class="muted">No chat history.</p>';
 return `<div class="dsh"><div><div class="subtabs" role="tablist">${[['summary','Summary'],['notes','Notes']].map(([k,l])=>`<button role="tab" type="button" aria-selected="${tab===k}" data-act="mdSub" data-id="${k}">${l}</button>`).join('')}</div>${tab==='summary'?`<div class="wg">${widgets}</div>`:(cv?`<div class="panel"><div class="pb" style="padding-top:12px"><ul class="mlist">${notes.map(n=>`<li><span><b>${n.date}, ${n.au}</b><br><span class="muted">${esc((n.S||'').slice(0,100))}</span></span><span>${chip(n.st==='signed'?'ok':'warn',n.st==='signed'?'Signed':'Draft')}${n.conf?chip('neu','Confidential'):''}<button class="btn sm" type="button" data-act="viewNote" data-id="${n.id}">Open</button></span></li>`).join('')||'<li class="muted">No consultation notes.</li>'}</ul></div></div>`:`<div class="notice">Notes are restricted for this role.</div>`)}</div>
 <aside><div class="subtabs" role="tablist">${[['ph','Preventative health'],['ch','Chat history']].map(([k,l])=>`<button role="tab" type="button" aria-selected="${pt===k}" data-act="mdPT" data-id="${k}">${l}</button>`).join('')}</div><div class="panel"><div class="pb" style="padding-top:12px">${pt==='ph'?al+'<p class="hint">Based on RACGP Red Book prompts (demo list). Plus creates a clinical action.</p>':chat}</div></div></aside></div>`}
ACT.mdSub=el=>{UI.dsub=el.dataset.id;R()};ACT.mdPT=el=>{UI.pdt=el.dataset.id;R()};
// details
function mdDetails(p){return `<div class="grid2"><div class="col">${pnl('md-d','Demographics',`<dl class="kv"><dt>Name</dt><dd>${esc(nm(p))}</dd><dt>Date of birth</dt><dd>${dobS(p.dob)} (${age(p.dob)} years)</dd><dt>Sex</dt><dd>${SEXL[p.sex]||p.sex}</dd><dt>Mobile</dt><dd>${esc(p.ph)||'Not recorded'}</dd><dt>Header note</dt><dd>${esc(p.hdr||'None')}</dd></dl><div class="row-actions"><button class="btn sm" type="button" data-act="mdEdit" data-id="${p.id}">Edit details</button></div>`,'')}</div><div class="col">${pnl('md-i','Identifiers',`<dl class="kv"><dt>Medicare</dt><dd>${mcm(p)} (masked)</dd><dt>IHI</dt><dd>${chip('neu','Not validated (simulated)')}</dd><dt>DVA</dt><dd>None</dd><dt>Private health fund</dt><dd>None recorded</dd></dl><p class="hint">Health Identifiers service is not connected in this mockup.</p>`,'simulated')}${pnl('md-r','Referrals on file',refRows(S.ref.filter(x=>x.p===p.id)),'')}</div></div>`}
ACT.mdEdit=el=>{if(!need('patient','Editing patient details'))return;const p=P(el.dataset.id);formModal({title:'Edit details',fields:[{k:'ph',l:'Mobile',v:p.ph},{k:'hdr',l:'Note shown in the patient header',v:p.hdr||'',hint:'Short, visible to everyone who opens the record.'}],save:v=>{p.ph=v.ph;p.hdr=v.hdr;audit('Edited patient details',nm(p));persist();R();toast('Saved.')}})};
// clinical
const CSEC=[['today',"Today's notes"],['notes','Clinical notes'],['allergies','Allergies and reactions'],['history','Medical history'],['past','Past consultations'],['medications','Medications'],['immunisations','Immunisations'],['investigations','Investigations'],['correspondence','Correspondence'],['observations','Observations'],['templates','Clinical templates'],['obstetrics','Obstetrics and screening'],['social','Social history']];
function mdToday(p){const a=S.appts.find(x=>x.p===p.id&&x.d===0&&x.st==='with');
 if(!a){const nx=S.appts.find(x=>x.p===p.id&&x.d===0&&['arrived','booked','online'].includes(x.st));return `<div class="notice">No consultation in progress for ${esc(nm(p))}.</div><div class="row-actions">${nx?`<button class="btn pri" type="button" data-act="start" data-id="${nx.id}">Start consultation (${hm(nx.t)})</button>`:`<button class="btn pri" type="button" data-act="newAppt" data-p="${p.id}">Book appointment</button>`}</div>`}
 const c=consultParts(a),n=c.n,ed=n.st==='draft',mins=Math.max(0,now()-(a.arr||a.t));
 const ins=[['Reason','S','Reason for visit: '+(a.why||'')],['Observation','O','Observations: '+(p.obs.slice(0,2).map(o=>o[0]+' '+o[1]+' '+o[2]).join(', ')||'none recorded')],['Examination','O','Examination: '],['Procedure','P','Procedure: '],['Diagnosis','A','Diagnosis (code search is simulated): '],['Shortcuts','S','Shortcut text: '],['New EPC','P','Enhanced primary care plan to be prepared.'],['Cases','A','Case: ']];
 return `<div class="cmeta"><label>Type <select disabled><option>${TYPES[a.ty][0]}</option></select></label><span>${dayName(0)}, ${hm(a.t)}</span><span>Room 2</span><span>${chip('info','Consult timer '+mins+' min, running (simulated)')}</span><span class="muted">Autosaves as you type.</span></div>${ed?`<div class="ins" role="group" aria-label="Insert into note">${ins.map(([l,k,t])=>`<button class="btn sm" type="button" data-act="mdIns" data-id="${n.id}" data-k="${k}" data-t="${esc(t)}">${l}</button>`).join('')}</div>`:''}${c.note}${c.scribe}${c.rx}${c.ref}${c.ord}`}
ACT.mdIns=el=>{const n=S.notes.find(x=>x.id==el.dataset.id);if(!n||n.st!=='draft')return;n[el.dataset.k]+=(n[el.dataset.k]?'\n':'')+el.dataset.t;persist();R();const t=$('#n-'+el.dataset.k);t&&t.focus()};
ACT.mdAlg=el=>{if(!need('clin.write','Adding an allergy'))return;const p=P(el.dataset.id);formModal({title:'Add allergy or reaction',fields:[{k:'s',l:'Substance',req:true},{k:'r',l:'Reaction',t:'select',o:['Rash','Hives','Anaphylaxis','Nausea','Other'].map(x=>[x,x])},{k:'sev',l:'Severity',t:'select',o:['Mild','Moderate','Severe'].map(x=>[x,x])}],save:v=>{p.al.push(v.s);(p.alx=p.alx||[]).push([v.s,v.r,v.sev]);audit('Added allergy',nm(p));persist();R();toast('Allergy saved. Alerts in the header update.')}})};
ACT.mdCond=el=>{if(!need('clin.write','Adding a condition'))return;const p=P(el.dataset.id);formModal({title:'Add to medical history',fields:[{k:'c',l:'Condition',req:true,hint:'Code search is simulated.'},{k:'y',l:'Since (year)',req:true,chk:v=>/^\d{4}$/.test(v)?'':'Use a 4 digit year.'},{k:'s',l:'Status',t:'select',o:['Active','Resolved','Inactive'].map(x=>[x,x])}],save:v=>{p.hx.push([v.c,v.y,v.s]);audit('Added condition',nm(p));persist();R()}})};
ACT.mdConf=el=>{if(!need('clin.write'))return;const n=S.notes.find(x=>x.id==el.dataset.id);n.conf=!n.conf;audit(n.conf?'Marked note confidential':'Removed confidential flag',nm(P(n.p)));persist();R()};
function mdClinical(p,sec){const cw=can('clin.write'),sub=sec||'today',P2=x=>pnl('mc-'+sub,x[0],x[1],x[2]||'');
 const body={
 today:()=>mdToday(p),
 notes:()=>ntPage(p),social:()=>ntSocial(p),
 allergies:()=>P2(['Allergies and reactions',`<ul class="mlist">${p.al.map(a=>{const x=(p.alx||[]).find(y=>y[0]===a);return `<li><span><b class="red">${esc(a)}</b>${x?`, ${x[1]}, ${x[2]}`:''}</span>${chip('bad','Allergy alert (keyword demo)')}</li>`}).join('')||'<li class="muted">No known allergies recorded</li>'}</ul><div class="row-actions"><button class="btn" type="button" data-act="mdAlg" data-id="${p.id}">Add allergy</button></div><p class="hint">Allergy warnings are keyword demos, not clinical advice.</p>`]),
 history:()=>P2(['Medical history',`<ul class="mlist">${p.hx.map(h=>`<li><span><b>${esc(h[0])}</b>, since ${h[1]}</span>${chip(h[2]==='Active'?'info':'neu',h[2])}</li>`).join('')||'<li class="muted">None recorded</li>'}</ul><div class="row-actions"><button class="btn" type="button" data-act="mdCond" data-id="${p.id}">Add condition</button></div>`]),
 past:()=>P2(['Past consultations',`<ul class="mlist">${S.notes.filter(n=>n.p===p.id).reverse().map(n=>`<li><span><b>${n.date}, ${n.au}</b><br><span class="muted">${esc((n.S||'').slice(0,110))}</span></span><span>${chip(n.st==='signed'?'ok':'warn',n.st==='signed'?'Signed, locked':'Draft')}${n.conf?chip('neu','Confidential'):''}<button class="btn sm" type="button" data-act="viewNote" data-id="${n.id}">Open</button>${cw?`<button class="btn sm" type="button" data-act="mdConf" data-id="${n.id}">${n.conf?'Remove confidential':'Mark confidential'}</button>`:''}</span></li>`).join('')||'<li class="muted">No consultations.</li>'}</ul>`]),
 medications:()=>P2(['Medications',`<h3>Current</h3><ul class="mlist">${p.meds.filter(m=>m[2]==='reg').map(m=>`<li><span><b>${m[0]}</b> ${m[1]}</span>${chip('neu','Regular')}</li>`).join('')||'<li class="muted">None</li>'}${p.meds.filter(m=>m[2]==='prn').map(m=>`<li><span><b>${m[0]}</b> ${m[1]}</span>${chip('neu','As needed')}</li>`).join('')}</ul><h3>Ceased</h3><ul class="mlist">${p.meds.filter(m=>m[2]==='off').map(m=>`<li><span><b>${m[0]}</b> ${m[1]}</span></li>`).join('')||'<li class="muted">None</li>'}</ul><h3>Scripts</h3>${rxRows(S.rx.filter(x=>x.p===p.id))}<div class="row-actions"><button class="btn pri" type="button" data-act="addRx" data-id="${p.id}">Write prescription</button><button class="btn" type="button" data-act="toastC" data-m="Active script list lookup (simulated). Nothing was requested.">Active script list (simulated)</button></div>${chip('neu','MIMS sample data, not connected')}`]),
 immunisations:()=>P2(['Immunisations and AIR',`<ul class="integ">${p.imm.map(i=>`<li><b>${i.v}</b>${stChip(i.air)}<span class="d">${i.d}. ${airBtn(p,i)}</span></li>`).join('')||'<li class="muted">None recorded.</li>'}</ul><div class="row-actions"><button class="btn pri" type="button" data-act="addImm" data-id="${p.id}">Record immunisation</button><button class="btn" type="button" data-act="toastC" data-m="AIR access check (simulated). Nothing was requested.">Check AIR access (simulated)</button></div>`,'AIR simulated']),
 investigations:()=>P2(['Requests and results',`<h3>Requests</h3>${S.orders.filter(o=>o.p===p.id).map(o=>`<div class="q"><span><b>${esc(o.test)}</b> ${o.kind}</span>${chip('neu','Saved locally, not transmitted')}</div>`).join('')||'<p class="muted">No requests.</p>'}<div class="row-actions"><button class="btn" type="button" data-act="addOrd" data-id="${p.id}">New request</button></div><h3>Results</h3>${resRows(S.results.filter(r=>r.p===p.id))}`]),
 correspondence:()=>P2(['Correspondence',`<h3>In</h3><ul class="mlist">${S.msgs.filter(m=>m.p===p.id&&m.dir==='in').map(m=>`<li><span><b>${esc(m.sub)}</b><br><span class="muted">${esc(m.from)}</span></span><button class="btn sm" type="button" data-act="msgOpen" data-id="${m.id}">Open</button></li>`).join('')||'<li class="muted">None</li>'}</ul><h3>Out</h3>${refRows(S.ref.filter(x=>x.p===p.id))}${S.msgs.filter(m=>m.p===p.id&&m.dir==='out').map(m=>`<div class="q"><span><b>${esc(m.sub)}</b></span>${m.st==='fail'?stChip('fail')+`<button class="btn sm" type="button" data-act="msgRetry" data-id="${m.id}">Retry send</button>`:stChip('sent')}</div>`).join('')}<div class="row-actions"><button class="btn pri" type="button" data-act="addRef" data-id="${p.id}">New letter or referral</button></div>`]),
 observations:()=>P2(['Observations and vitals',`<div class="scroll-x"><table class="tbl"><thead><tr><th>Measure</th><th>Value</th><th>When</th><th>By</th></tr></thead><tbody>${p.obs.map(o=>`<tr><td>${o[0]}</td><td class="num">${o[1]} ${o[2]}</td><td>${o[3]}</td><td>${o[4]}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">None recorded.</td></tr>'}</tbody></table></div><div class="row-actions"><button class="btn" type="button" data-act="addObs" data-id="${p.id}">Add observation</button></div><p class="hint">Values and units only. PMS does not interpret observations.</p>`]),
 templates:()=>P2(['Clinical templates',`<ul class="mlist">${['GP management plan','Team care arrangement','Health assessment, 75 and over','Mental health treatment plan','Cervical screening record','Antenatal visit'].map(t=>`<li><span>${t}</span><button class="btn sm" type="button" data-act="toastC" data-m="${t}: template opens here in a real build (demo).">Open template</button></li>`).join('')}</ul>`]),
 obstetrics:()=>P2(['Obstetrics and cervical screening',p.sex==='F'?`<p class="muted">No pregnancy details recorded.</p><p>Cervical screening: ${p.flags.some(f=>/screening/i.test(f))?chip('warn','Due'):chip('ok','Up to date')}</p><div class="row-actions"><button class="btn" type="button" data-act="toastC" data-m="Result recorded locally (demo).">Record screening result</button></div>`:'<p class="muted">Not applicable for this patient.</p>'])};
 return `<div class="clin"><nav class="csn" aria-label="Clinical sections">${CSEC.map(([k,l])=>`<a href="#/pts/${p.id}/clinical/${k}" ${sub===k?'aria-current="page"':''}>${l}</a>`).join('')}</nav><div class="col">${(body[sub]||body.today)()}</div></div>`}
function mdAccounts(p){return `${pnl('ma','Invoices and claims',invRows(S.inv.filter(i=>i.p===p.id)),'Balance '+money(bal(p.id)))}<div class="row-actions"><button class="btn pri" type="button" data-act="mdInv" data-id="${p.id}">New invoice</button><a class="btn" href="#/bill/claims">Claiming dashboard</a></div>`}
ON.mdCons=el=>{const p=P(el.dataset.id),c=p.cons[+el.dataset.i];c[2]=el.checked?'on':'off';c[1]=el.checked?'Recorded '+hm(now()):'Withdrawn '+hm(now());audit((el.checked?'Consent recorded: ':'Consent withdrawn: ')+c[0],nm(p));persist();R()};
function mdConsent(p){return pnl('mcs','Consent',`<ul class="mlist">${p.cons.map((c,i)=>`<li><span><label for="cn${i}"><b>${c[0]}</b></label><br><span class="muted">${c[1]}</span></span><span><input type="checkbox" id="cn${i}" ${c[2]==='on'?'checked':''} data-on="mdCons" data-id="${p.id}" data-i="${i}" style="width:22px;height:22px;accent-color:var(--brand)"></span></li>`).join('')}</ul><p class="hint">AI scribe consent is asked per visit, inside Today's notes.</p>`,'')}
function mdActivities(p){const L2=S.tasks.filter(t=>t.p===p.id);return pnl('mac','Activities and clinical actions',`<ul class="tasks">${L2.map(t=>`<li><input type="checkbox" id="t${t.id}" ${t.done?'checked':''} data-on="task" data-id="${t.id}"><label for="t${t.id}">${t.done?'<s>':''}${esc(t.t)}${t.done?'</s>':''} <span class="muted">${ROLE[t.who]}, ${esc(t.due)}</span></label></li>`).join('')||'<li class="muted">No activities for this patient.</li>'}</ul><div class="row-actions"><button class="btn pri" type="button" data-act="mdCA" data-id="${p.id}">New clinical action</button></div>`,L2.filter(t=>!t.done).length+' open')+pnl('mar','Recalls',recRows(S.recalls.filter(r=>r.p===p.id)),'')}
function mdAudit(p){const L2=S.audit.filter(a=>a.e&&a.e.includes(nm(p)));return pnl('mad','Audit, this patient',`<div class="scroll-x"><table class="tbl"><thead><tr><th>Time</th><th>Who</th><th>What</th></tr></thead><tbody>${L2.slice(0,40).map(a=>`<tr><td class="num">${a.t}</td><td>${a.r}</td><td>${esc(a.a)}</td></tr>`).join('')||'<tr><td colspan="3" class="muted">No entries yet.</td></tr>'}</tbody></table></div><p class="hint">Every open, edit and send is logged. Break-glass access: none.</p>`,L2.length+' entries')}
VIEWS.pts=r=>{const p=r.a&&P(r.a);if(!p)return mdPtList();let tab=r.b||'dashboard',sec=r.c;if(ALIAS[tab]){sec=sec||ALIAS[tab][1];tab=ALIAS[tab][0]}
 const clin=can('clin.view');
 const inner={dashboard:()=>mdDash(p),details:()=>mdDetails(p),clinical:()=>clin?mdClinical(p,sec):restricted('The clinical record'),accounts:()=>(can('billing')||can('bill.view'))?mdAccounts(p):restricted('Accounts'),consent:()=>mdConsent(p),activities:()=>mdActivities(p),audit:()=>mdAudit(p)}[tab]||(()=>mdDash(p));
 return `<div class="vh"><a href="#/pts" class="back">Patients</a></div>${mdHdr(p)}<div class="tabs mdt" role="tablist">${TABS.map(([k,l])=>`<a role="tab" href="#/pts/${p.id}/${k}" aria-selected="${tab===k}">${l}</a>`).join('')}</div>${mdQA(p)}${inner()}`};
// ---- secure messaging inbox ----
ON.rq=el=>{UI.rq=el.value;R()};
ACT.mdResCA=el=>{const r=S.results.find(x=>x.id==el.dataset.id);ACT.mdCA({dataset:{id:r.p||''}})};
VIEWS.res=r=>{if(!can('results')&&!can('comms'))return `<div class="vh"><h1>Inbox</h1></div>${restricted('The secure messaging inbox')}`;let t=r.a||'results';const q=(UI.rq||'').toLowerCase();if((t==='results'||t==='holding')&&!can('results')&&can('comms'))t='denied';
 const R1=S.results.filter(x=>x.st!=='unmatched'),H=S.results.filter(x=>x.st==='unmatched'),C=S.msgs.filter(m=>m.dir==='in'),O=[...S.ref.map(x=>({id:'r'+x.id,s:x.to,st:x.st,sub:x.why,rid:x.id,k:'ref'})),...S.msgs.filter(m=>m.dir==='out').map(m=>({id:'m'+m.id,s:m.from,st:m.st==='fail'?'fail':'sent',sub:m.sub,mid:m.id,k:'msg'}))];
 const f=(arr,fn)=>arr.filter(x=>!q||fn(x).toLowerCase().includes(q));
 const tabs=[['results','Results',R1.filter(x=>x.st==='review').length],['correspondence','Correspondence',C.filter(m=>m.st==='unread').length],['outbox','Outbox',O.filter(x=>x.st==='fail').length],['holding','Holding bay',H.length]];
 let list='';
 if(t==='denied')list=restricted('Results and the holding bay (clinicians only; you can use correspondence and the outbox)');
 else if(t==='results')list=f(R1,x=>x.test+nm(P(x.p))).map(x=>`<div class="it"><div class="n"><b>${esc(x.test)}</b> ${chip('neu',x.kind)}<small>${esc(nm(P(x.p)))}, received ${x.at}. ${esc(x.flag)}.</small></div>${x.st==='reviewed'?chip('ok','Reviewed and filed by '+x.by):chip('warn','Needs review')}${x.st==='review'?`<button class="btn pri sm" type="button" data-act="resRev" data-id="${x.id}">Review and file</button>`:''}<button class="btn sm" type="button" data-act="mdResCA" data-id="${x.id}">Create clinical action</button><a class="btn sm" href="#/pts/${x.p}/clinical/investigations">Open record</a></div>`).join('');
 else if(t==='correspondence')list=f(C,x=>x.sub+x.from).map(x=>`<div class="it"><div class="n"><b>${esc(x.sub)}</b><small>${esc(x.from)}${x.p?', '+esc(nm(P(x.p))):''}</small></div>${x.st==='unread'?chip('info','Unread'):chip('neu','Read')}<button class="btn sm" type="button" data-act="msgOpen" data-id="${x.id}">Open</button>${x.p?`<button class="btn sm" type="button" data-act="mdCA" data-id="${x.p}">Create clinical action</button>`:''}</div>`).join('');
 else if(t==='outbox')list=f(O,x=>x.s+x.sub).map(x=>`<div class="it"><div class="n"><b>${esc(x.sub)}</b><small>To ${esc(x.s)}</small></div>${stChip(x.st)}${x.st==='fail'?`<button class="btn sm" type="button" data-act="${x.k==='ref'?'refSend':'msgRetry'}" data-id="${x.rid||x.mid}">Retry send (simulated)</button>`:''}${x.st==='sent'&&x.k==='ref'?`<button class="btn sm" type="button" data-act="refAck" data-id="${x.rid}">Demo: delivered</button>`:''}</div>`).join('');
 else list=f(H,x=>x.test).map(x=>`<div class="it"><div class="n"><b>${esc(x.test)}</b> ${chip('neu',x.kind)}<small>${esc(x.flag)}. Received ${x.at}.</small></div>${chip('bad','Not matched to a patient')}<button class="btn pri sm" type="button" data-act="resMatch" data-id="${x.id}">Match patient</button></div>`).join('');
 return `<div class="vh"><h1>Secure messaging inbox</h1><button class="btn pri" type="button" data-act="msgNew">New message</button></div><div class="itabs" role="tablist" aria-label="Inbox">${tabs.map(([k,l,n])=>`<a role="tab" class="btn" style="${t===k?'background:var(--brand);color:var(--on-brand)':''}" aria-selected="${t===k}" href="#/res/${k}">${l} ${n?`<span class="chip c-warn">${n}</span>`:''}</a>`).join('')}</div><div class="fld" style="max-width:24rem"><label for="rq">Search this list</label><input id="rq" type="search" value="${esc(UI.rq||'')}" data-on="input" data-fn="rq"></div><div class="ibx" role="tabpanel">${list||'<p class="muted">Nothing here.</p>'}</div><p class="hint">Reviewed items are filed into the patient record. Unmatched items wait in the holding bay until a person confirms identity. Simulated feed, nothing is real.</p>${can('results')&&t==='results'?'<div class="demo-ctl pad" style="margin-top:12px">Demo control: <button class="btn sm" type="button" data-act="resNew">Simulate a result arriving</button></div>':''}`};
"""
build('medirecords','PMS vs MediRecords, clinical record',tokens,skin,vjs,os.path.join(D,'..','toolii-vs-medirecords.html'),post)
